-- 0051_challenge_sim_from_writeups.sql: auto-generated "challenge_sim"
-- simulation Q&A cards (mode="challenge_sim") for 21 THM challenge rooms that
-- already have a verified `writeup_url` in pentestChallenges.ts. Content was
-- synthesized by reading each writeup's methodology and distilling it into
-- technique/methodology-level questions (never literal flag values or
-- instance-specific IPs/hostnames, since those are unique per deployment and
-- not reusable). These cards render via the existing "Quan ly cau hoi" /
-- "Lam Simulation" UI in Labs.vue (same mechanism as user-authored
-- challenge_sim cards) -- pure self-practice, not part of the FSRS
-- spaced-repetition queue. A learner who later edits/overwrites via the UI
-- (PUT /cards/:id) simply updates this same row -- no special handling
-- needed since the app already supports edit-in-place for challenge_sim
-- cards. If a user already created their own challenge_sim card with the
-- exact same front text before this migration runs, ON CONFLICT ... DO
-- NOTHING preserves their version untouched.

INSERT INTO cards (deck_id, kind, front, payload, source)
SELECT d.id, 'lab', c.front, c.payload::jsonb, 'seed'
FROM (VALUES
  ('[Simulation] THM — Jr Penetration Tester (learning path chính thức)', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Jr Penetration Tester (learning path chính thức)\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Trong giai đoạn trinh sát (reconnaissance) của lộ trình Jr Penetration Tester, công cụ nào được dùng để khám phá host, cổng dịch vụ đang mở và chạy script dò lỗ hổng (vulnerability scripting)?", "patterns": ["nmap"], "explanation": "Nmap là công cụ quét mạng chủ đạo, cho phép dò cổng, nhận diện dịch vụ/phiên bản (-sV) và chạy các script NSE để phát hiện lỗ hổng đã biết.", "hint": "Công cụ dòng lệnh quét cổng và dịch vụ phổ biến nhất trong pentest."}, {"prompt": "Để tự động hóa tấn công brute-force vào form đăng nhập web hoặc dịch vụ mạng (SSH, FTP...) trong lộ trình này, công cụ nào thường được sử dụng?", "patterns": ["hydra"], "explanation": "Hydra là công cụ brute-force đa năng, hỗ trợ nhiều giao thức (HTTP form, SSH, FTP, RDP...) để dò mật khẩu bằng wordlist.", "hint": "Công cụ brute-force nổi tiếng của THC, tên loài quái vật nhiều đầu."}, {"prompt": "Khi đã xác định được phiên bản phần mềm/dịch vụ trên máy mục tiêu, kỹ thuật/công cụ nào giúp tra cứu nhanh các exploit công khai đã biết cho phiên bản đó ngay trên terminal?", "patterns": ["searchsploit", "exploit[- ]?db"], "explanation": "Searchsploit (bản offline của Exploit-DB) cho phép tìm kiếm exploit theo tên phần mềm/phiên bản mà không cần lên mạng.", "hint": "Công cụ dòng lệnh đi kèm Exploit-DB, dùng để tìm PoC/exploit có sẵn."}, {"prompt": "Trong module leo thang đặc quyền (privilege escalation) của lộ trình, các kịch bản thực hành tập trung vào việc khai thác điều gì trên cả Linux và Windows để chuyển từ user thường lên quyền cao hơn?", "patterns": ["misconfig", "cấu hình sai", "sai cấu hình"], "explanation": "Privilege escalation trong lộ trình này xoay quanh việc tìm và khai thác các lỗi cấu hình sai (quyền sudo, SUID, service path, registry...) thay vì lỗ hổng phần mềm phức tạp.", "hint": "Không phải lỗ hổng 0-day mà là lỗi do cấu hình hệ thống không chặt."}], "difficulty": "co_ban", "cert_tags": ["THM PT1"], "challenge_key": "THM:Jr Penetration Tester (learning path chính thức)"}'),
  ('[Simulation] THM — Web Application Pentesting (learning path chính thức)', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Web Application Pentesting (learning path chính thức)\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Lộ trình Web Application Pentesting nhấn mạnh việc dùng công cụ proxy nào để chặn, xem và chỉnh sửa (intercept/modify) các request/response HTTP trước khi gửi tới server?", "patterns": ["burp\\s*suite", "burp"], "explanation": "Burp Suite là proxy trung gian chủ đạo trong pentest web, cho phép chặn, sửa, replay request để kiểm tra logic và lỗ hổng phía server.", "hint": "Proxy pentest web phổ biến nhất, có bản Community miễn phí."}, {"prompt": "Kỹ thuật tấn công nào lợi dụng việc ứng dụng web render (hiển thị) dữ liệu người dùng trực tiếp vào một template engine (ví dụ Jinja2, Twig...), cho phép kẻ tấn công thực thi mã trên server?", "patterns": ["ssti", "server[- ]?side template injection"], "explanation": "SSTI (Server-Side Template Injection) xảy ra khi input người dùng được truyền thẳng vào template engine mà không lọc, dẫn đến thực thi mã tùy ý trên server.", "hint": "Tên viết tắt gồm 4 chữ cái, liên quan đến ''template injection'' ở phía server."}, {"prompt": "Lỗ hổng nào liên quan đến việc ứng dụng XML cho phép tham chiếu tới các thực thể ngoài (external entity), từ đó đọc được file nội bộ trên server hoặc thực hiện SSRF?", "patterns": ["xxe", "xml external entity"], "explanation": "XXE (XML External Entity) khai thác tính năng parser XML xử lý DOCTYPE/entity ngoài, cho phép đọc file hệ thống hoặc gửi request ra ngoài từ server.", "hint": "Viết tắt 3 chữ, liên quan tới XML và ''external entity''."}, {"prompt": "Kỹ thuật nào khiến server bị ép gửi request đến một địa chỉ/nội bộ do kẻ tấn công chỉ định (ví dụ để truy cập metadata service nội bộ hoặc dịch vụ chỉ cho phép localhost)?", "patterns": ["ssrf", "server[- ]?side request forgery"], "explanation": "SSRF (Server-Side Request Forgery) lợi dụng server thực hiện request thay cho kẻ tấn công tới tài nguyên nội bộ mà bình thường không thể truy cập từ ngoài.", "hint": "Viết tắt 4 chữ, trong đó có từ ''request forgery''."}, {"prompt": "Khi hai thiết bị trung gian (ví dụ load balancer và backend) hiểu sai lệch nhau về ranh giới của một request HTTP (do Content-Length/Transfer-Encoding), dẫn đến chèn request độc hại vào luồng của người dùng khác, đây là kỹ thuật gì?", "patterns": ["http\\s*smuggling", "request smuggling"], "explanation": "HTTP Request Smuggling khai thác sự khác biệt trong cách các tầng xử lý header Content-Length/Transfer-Encoding, cho phép ''giấu'' một request trong request khác.", "hint": "Kỹ thuật ''lậu'' request HTTP qua các tầng proxy/backend không đồng nhất cách parse."}], "difficulty": "co_ban", "cert_tags": ["THM WEB1"], "challenge_key": "THM:Web Application Pentesting (learning path chính thức)"}'),
  ('[Simulation] THM — Cyber Security 101', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Cyber Security 101\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Lộ trình Cyber Security 101 trên THM thường bắt đầu bằng room ''Offensive Security Intro'' để giới thiệu tổng quan. Theo em, mục tiêu chính của một room ''intro'' như vậy trong lộ trình nhập môn an ninh mạng là gì?", "patterns": ["giới thiệu", "tổng quan", "nhập môn", "overview", "khái niệm cơ bản"], "explanation": "Các room intro giới thiệu khái niệm cơ bản về offensive security (red team, các loại kiểm thử, quy trình pentest) để người mới có nền tảng trước khi học sâu từng kỹ thuật.", "hint": "Đây là room mở đầu, mục tiêu không phải khai thác sâu mà là xây nền tảng khái niệm."}, {"prompt": "Cyber Security 101 là lộ trình nhập môn bao quát nhiều lĩnh vực (mạng, web, Linux, Windows...). Vì sao một lộ trình như vậy thường được khuyến nghị học TRƯỚC các lộ trình chuyên sâu như Jr Penetration Tester?", "patterns": ["nền tảng", "cơ bản trước", "kiến thức nền", "foundation", "prerequisite"], "explanation": "Lộ trình nhập môn xây dựng kiến thức nền (mạng, hệ điều hành, khái niệm bảo mật) mà các lộ trình chuyên sâu về pentest giả định người học đã có sẵn.", "hint": "Nghĩ về vai trò ''nền tảng'' so với ''chuyên sâu'' trong lộ trình học."}, {"prompt": "Trong các lộ trình nhập môn an ninh mạng dạng này, kỹ năng thực hành tối thiểu nào về dòng lệnh (terminal) thường được yêu cầu trước khi học tấn công/phòng thủ cụ thể?", "patterns": ["linux", "command line", "dòng lệnh", "terminal", "bash"], "explanation": "Thao tác cơ bản trên dòng lệnh Linux (di chuyển thư mục, quyền file, chạy công cụ) là nền tảng bắt buộc vì hầu hết công cụ pentest chạy trên terminal Linux.", "hint": "Hầu hết công cụ pentest/CTF chạy trên môi trường nào, đòi hỏi kỹ năng gì?"}], "difficulty": "co_ban", "cert_tags": ["THM PT1"], "challenge_key": "THM:Cyber Security 101"}'),
  ('[Simulation] THM — Blue', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Blue\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Ở bước quét ban đầu trên máy mục tiêu Windows trong room Blue, loại script Nmap nào được dùng để tự động phát hiện các dịch vụ có lỗ hổng đã biết (bao gồm lỗ hổng SMB)?", "patterns": ["vuln", "--script\\s*vuln", "nmap.*vuln"], "explanation": "Chạy Nmap với nhóm script ''vuln'' (--script vuln) giúp tự động đối chiếu dịch vụ phát hiện được với các lỗ hổng đã biết, từ đó lộ ra dịch vụ SMB dính MS17-010.", "hint": "Nmap có một nhóm NSE script chuyên dò lỗ hổng, tên nhóm chỉ gồm 4 chữ."}, {"prompt": "Lỗ hổng SMB nổi tiếng được khai thác trong room Blue có mã CVE/bulletin là gì, và exploit tương ứng thường dùng trong Metasploit tên là gì?", "patterns": ["ms17-?010", "eternalblue"], "explanation": "MS17-010 là bulletin bảo mật của Microsoft cho lỗ hổng SMBv1; module khai thác tương ứng trong Metasploit tên là EternalBlue, cho phép thực thi mã từ xa với quyền SYSTEM.", "hint": "Đây là lỗ hổng SMB từng bị dùng trong mã độc WannaCry."}, {"prompt": "Sau khi có được một shell cơ bản (ví dụ reverse shell) từ exploit MS17-010, Metasploit cung cấp module post-exploitation nào để nâng cấp shell đó thành một session mạnh hơn, hỗ trợ nhiều lệnh và module hậu khai thác hơn?", "patterns": ["meterpreter", "shell_to_meterpreter", "sessions.*upgrade"], "explanation": "Metasploit có module chuyển đổi shell thường thành session Meterpreter, cung cấp nhiều tính năng hậu khai thác như migrate, hashdump, file search...", "hint": "Đây là loại payload/session đặc trưng của Metasploit Framework, mạnh hơn shell thường."}, {"prompt": "Vì tiến trình khai thác ban đầu có thể không ổn định hoặc không chạy ở quyền SYSTEM thực sự, kỹ thuật nào trong Meterpreter cho phép chuyển session sang chạy bên trong một tiến trình hệ thống ổn định hơn (ví dụ services.exe)?", "patterns": ["migrate"], "explanation": "Lệnh migrate trong Meterpreter cho phép di chuyển session sang một process ID khác đang chạy với quyền cao và ổn định hơn, tránh mất session khi process ban đầu bị tắt.", "hint": "Lệnh Meterpreter dùng để ''di cư'' sang tiến trình khác, tên tiếng Anh nghĩa là di trú."}, {"prompt": "Sau khi có quyền SYSTEM, kỹ thuật nào được dùng để trích xuất các mật khẩu dạng hash (NTLM) từ cơ sở dữ liệu tài khoản local, và công cụ offline nào thường dùng để bẻ (crack) các hash đó bằng wordlist?", "patterns": ["hashdump", "john( the ripper)?"], "explanation": "Lệnh hashdump trong Meterpreter trích xuất hash NTLM từ SAM database; John the Ripper (với wordlist như rockyou.txt và định dạng NT) dùng để crack các hash này offline.", "hint": "Một lệnh Meterpreter để ''đổ'' hash, và một công cụ crack hash kinh điển mang tên ''Ripper''."}], "difficulty": "co_ban", "cert_tags": ["THM PT1"], "challenge_key": "THM:Blue"}'),
  ('[Simulation] THM — Linux PrivEsc', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Linux PrivEsc\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Trước khi thử bất kỳ kỹ thuật leo thang đặc quyền nào trên Linux, bước đầu tiên và quan trọng nhất theo phương pháp luận của room này là gì?", "patterns": ["enum", "thu thập thông tin", "liệt kê"], "explanation": "Enumeration (thu thập thông tin hệ thống: kernel, sudo quyền, cron, SUID, tiến trình...) là bước nền tảng để xác định hướng leo thang khả thi, trước khi thử khai thác.", "hint": "Phương pháp luận privesc luôn bắt đầu bằng việc ''liệt kê/thu thập'' trước khi khai thác."}, {"prompt": "Nếu phiên bản kernel của máy Linux mục tiêu quá cũ và có lỗ hổng công khai, công cụ dòng lệnh nào giúp tra cứu nhanh exploit tương ứng, và sau khi tìm được thì cần làm gì với mã nguồn đó trên máy mục tiêu?", "patterns": ["searchsploit"], "explanation": "Searchsploit giúp tra cứu exploit theo phiên bản kernel; sau đó cần chuyển mã nguồn lên máy mục tiêu, biên dịch (compile) rồi chạy để leo quyền root.", "hint": "Công cụ tra cứu Exploit-DB ngay trên terminal."}, {"prompt": "Khi người dùng hiện tại được phép chạy một số binary bằng sudo (kiểm tra qua lệnh liệt kê quyền sudo), trang web/nguồn tài liệu nào thường được dùng để tra xem binary đó có thể bị lợi dụng để spawn shell quyền cao hơn không?", "patterns": ["gtfobins"], "explanation": "GTFOBins là cơ sở dữ liệu liệt kê cách các binary Unix hợp pháp (find, vim, less...) có thể bị lạm dụng để thoát ra shell hoặc leo quyền khi có quyền sudo/SUID trên chúng.", "hint": "Trang tổng hợp cách lợi dụng các lệnh Unix hợp pháp để bypass giới hạn, tên viết tắt từ một câu chửi tiếng Anh."}, {"prompt": "Loại file đặc biệt nào trên Linux, khi được set một bit quyền nhất định, sẽ luôn chạy với quyền của chủ sở hữu file (thường là root) bất kể ai thực thi nó, và đây là mục tiêu cần rà soát trong quá trình leo thang đặc quyền?", "patterns": ["suid"], "explanation": "File có bit SUID sẽ thực thi với quyền của owner (thường root) chứ không phải quyền người chạy; tìm các binary SUID bất thường rồi đối chiếu GTFOBins là kỹ thuật phổ biến.", "hint": "Bit quyền đặc biệt (Set User ID) trên Linux, thường tìm bằng lệnh find kèm -perm."}, {"prompt": "Nếu phát hiện một tác vụ được lập lịch chạy định kỳ với quyền root nhưng lại thực thi một script mà user thường có quyền ghi (writable), đây là lỗ hổng leo thang đặc quyền thuộc loại nào, và cơ chế lập lịch đó trên Linux tên là gì?", "patterns": ["cron"], "explanation": "Đây là lỗ hổng khai thác qua cron job: nếu script được root chạy định kỳ có quyền ghi cho user thường, kẻ tấn công có thể sửa script để chèn lệnh chạy với quyền root ở lần kế tiếp.", "hint": "Cơ chế lập lịch chạy tác vụ định kỳ mặc định trên Linux, cấu hình trong crontab."}], "difficulty": "co_ban", "cert_tags": ["THM PT1"], "challenge_key": "THM:Linux PrivEsc"}'),
  ('[Simulation] THM — Windows PrivEsc', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Windows PrivEsc\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Giống như trên Linux, bước đầu tiên khi leo thang đặc quyền trên Windows là thu thập thông tin hệ thống. Ngoài danh sách user local, những thông tin nào về bản vá/bảo mật cần kiểm tra để biết máy có thiếu patch quan trọng hay không?", "patterns": ["hotfix", "patch", "windows update"], "explanation": "Kiểm tra các hotfix/bản vá đã cài (và thời điểm cài) giúp xác định máy có đang thiếu các bản vá bảo mật quan trọng, từ đó gợi ý các lỗ hổng leo quyền đã biết có thể áp dụng.", "hint": "Từ tiếng Anh chỉ các bản vá bảo mật nhỏ được Microsoft phát hành."}, {"prompt": "Khi liệt kê phần mềm cài trên máy Windows mục tiêu và đối chiếu phiên bản với các lỗ hổng đã biết, một dạng lỗ hổng phổ biến liên quan đến cấu hình dịch vụ (service) có đường dẫn thực thi chứa khoảng trắng nhưng không được đặt trong dấu ngoặc kép gọi là gì?", "patterns": ["unquoted service path", "unquoted path"], "explanation": "Lỗ hổng Unquoted Service Path xảy ra khi đường dẫn file thực thi của service chứa khoảng trắng mà không có dấu ngoặc kép bao quanh, khiến Windows có thể hiểu nhầm và chạy một executable giả do kẻ tấn công đặt ở thư mục cha.", "hint": "Tên lỗ hổng gồm hai từ tiếng Anh: ''không có dấu ngoặc kép'' + ''đường dẫn dịch vụ''."}, {"prompt": "Để khai thác lỗ hổng Unquoted Service Path, kẻ tấn công cần kiểm tra điều gì ở từng thư mục cha trong đường dẫn service đó trước khi đặt file thực thi độc hại vào?", "patterns": ["quyền ghi", "writable", "write permission"], "explanation": "Cần kiểm tra thư mục cha nào trong đường dẫn mà user hiện tại có quyền ghi (writable); đặt executable trùng tên đoạn đường dẫn đó vào sẽ bị Windows chạy nhầm khi service khởi động lại.", "hint": "Không phải mọi thư mục trong đường dẫn đều cho phép user thường ghi file vào."}, {"prompt": "Kỹ thuật leo thang đặc quyền nào lợi dụng việc một ứng dụng nạp một thư viện động (file .dll) từ thư mục không an toàn hoặc không chỉ định đường dẫn tuyệt đối, cho phép kẻ tấn công thay thế bằng file độc hại trùng tên?", "patterns": ["dll hijack"], "explanation": "DLL Hijacking khai thác thứ tự tìm kiếm DLL của Windows: nếu ứng dụng nạp DLL mà không chỉ rõ đường dẫn tuyệt đối, kẻ tấn công có thể đặt một DLL độc hại cùng tên vào thư mục được tìm trước, khiến mã độc được thực thi khi ứng dụng chạy.", "hint": "Tấn công liên quan đến việc ''cướp'' file thư viện động (.dll) mà ứng dụng nạp vào."}, {"prompt": "Sau khi xác định được dịch vụ bảo mật của hệ thống (ví dụ Windows Defender) đang ở trạng thái gì, điều này giúp kẻ tấn công quyết định điều gì khi chọn công cụ/payload để thực hiện leo thang đặc quyền?", "patterns": ["tắt", "disable", "trạng thái", "bị tắt hoặc bật"], "explanation": "Biết Windows Defender đang bật/tắt giúp kẻ tấn công quyết định có thể dùng payload thô (không mã hóa) hay cần obfuscation/encoding để tránh bị phát hiện trong quá trình leo thang.", "hint": "Phần mềm diệt virus mặc định của Windows có thể cản trở việc chạy payload leo quyền."}], "difficulty": "co_ban", "cert_tags": ["THM PT1"], "challenge_key": "THM:Windows PrivEsc"}'),
  ('[Simulation] THM — Reset', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Reset\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Trong hầu hết các bài lab pentest dạng ''boot-to-root'' như room Reset, bước đầu tiên bắt buộc trước khi tấn công là gì, và công cụ phổ biến nhất để thực hiện bước đó là gì?", "patterns": ["nmap", "quét cổng", "port scan"], "explanation": "Bước đầu tiên luôn là quét cổng/dịch vụ (thường bằng Nmap) để biết máy mục tiêu đang chạy dịch vụ gì, từ đó xác định hướng tấn công tiếp theo.", "hint": "Công cụ dòng lệnh quét cổng và nhận diện dịch vụ phổ biến nhất."}, {"prompt": "Sau khi tìm thấy một dịch vụ web hoặc ứng dụng chạy trên máy mục tiêu, bước tiếp theo trong phương pháp luận pentest là gì trước khi thử khai thác bất kỳ lỗ hổng cụ thể nào?", "patterns": ["enum", "liệt kê", "dò thư mục", "gobuster", "dirbuster"], "explanation": "Cần tiếp tục enumeration (ví dụ dò thư mục/endpoint bằng Gobuster, kiểm tra phiên bản phần mềm, tìm thông tin nhạy cảm) để hiểu rõ bề mặt tấn công trước khi khai thác.", "hint": "Giai đoạn ''thu thập thông tin sâu hơn'' sau khi đã biết dịch vụ đang chạy là gì."}, {"prompt": "Sau khi đã có được quyền truy cập ban đầu (initial access) vào máy mục tiêu với quyền hạn thấp, mục tiêu cuối cùng của giai đoạn tiếp theo trong một bài pentest boot-to-root là gì?", "patterns": ["privilege escalation", "leo thang đặc quyền", "leo quyền"], "explanation": "Mục tiêu tiếp theo là leo thang đặc quyền (privilege escalation), tức chuyển từ user quyền thấp lên quyền quản trị/root để kiểm soát hoàn toàn hệ thống.", "hint": "Từ quyền user thường, mục tiêu tiếp theo luôn là đạt được quyền cao nhất trên hệ thống."}], "difficulty": "co_ban", "cert_tags": ["THM PT1"], "challenge_key": "THM:Reset"}'),
  ('[Simulation] THM — NetSec Challenge', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"NetSec Challenge\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Trước khi khai thác bất kỳ dịch vụ nào, bạn cần biết các cổng (port) đang mở trên mục tiêu. Công cụ dòng lệnh phổ biến nhất để quét toàn bộ 65535 cổng TCP, phát hiện phiên bản dịch vụ và chạy script mặc định là gì?", "patterns": ["nmap"], "explanation": "Nmap là công cụ chuẩn để quét cổng, xác định dịch vụ/phiên bản (-sV) và chạy script enumeration mặc định (-sC), giúp phát hiện cả các cổng không tiêu chuẩn (ví dụ FTP chạy ở cổng lạ) mà một lần quét top-1000-port có thể bỏ sót.", "hint": "Công cụ bắt đầu bằng chữ n, dùng cờ -p- để quét hết các cổng."}, {"prompt": "Sau khi phát hiện một dịch vụ FTP chạy ở cổng không tiêu chuẩn và đã có danh sách username nghi ngờ (thu được qua kỹ thuật social engineering/OSINT), bạn muốn dò mật khẩu tự động bằng một wordlist phổ biến (ví dụ rockyou.txt). Công cụ brute-force đăng nhập dịch vụ mạng nào thường được dùng cho việc này?", "patterns": ["hydra", "medusa", "ncrack", "brute\\s*-?\\s*force"], "explanation": "Hydra là công cụ brute-force đăng nhập mạng rất phổ biến, hỗ trợ nhiều protocol (FTP, SSH, HTTP...), cho phép thử danh sách username/password lớn như rockyou.txt một cách tự động.", "hint": "Công cụ này viết tắt tên một con rắn nhiều đầu trong thần thoại Hy Lạp."}, {"prompt": "Một kỹ thuật thu thập username hoặc thông tin mục tiêu không dựa vào kỹ thuật kỹ thuật (technical) mà dựa vào việc khai thác yếu tố con người, thông tin công khai (ví dụ trang web, mạng xã hội, tài liệu rò rỉ) được gọi là gì?", "patterns": ["social\\s*engineering", "osint"], "explanation": "Social engineering (kỹ thuật xã hội) hoặc OSINT (Open Source Intelligence) là cách thu thập thông tin như tên người dùng từ các nguồn công khai hoặc tương tác con người, thay vì quét kỹ thuật thuần túy.", "hint": "Kỹ thuật này lợi dụng con người hoặc thông tin công khai, không phải lỗ hổng phần mềm."}, {"prompt": "Một tường lửa (firewall) có thể chặn các gói TCP SYN thông thường khiến nmap quét bình thường không phát hiện được cổng đang mở. Loại quét nmap nào gửi gói tin không có cờ nào (không SYN, không ACK...) để cố gắng né tránh firewall/IDS đơn giản, thường gọi là quét rỗng?", "patterns": ["null\\s*scan", "-sn\\b|-sN", "nmap.*null"], "explanation": "NULL scan (nmap -sN) gửi gói TCP không có cờ nào được bật. Một số firewall/host lọc theo cờ SYN sẽ không chặn kiểu quét này, giúp phát hiện cổng mà quét SYN thông thường bị chặn bởi tường lửa.", "hint": "Tên loại quét này nghĩa là ''rỗng'', không mang cờ TCP nào."}], "difficulty": "trung_binh", "cert_tags": ["THM PT1"], "challenge_key": "THM:NetSec Challenge"}'),
  ('[Simulation] THM — Stealth', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Stealth\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Phòng lab này tập trung vào việc vượt qua phần mềm diệt virus/EDR trên Windows (ví dụ Windows Defender) khi triển khai payload. Tên chung cho nhóm kỹ thuật giúp mã độc/payload không bị phần mềm bảo mật phát hiện được gọi là gì?", "patterns": ["av\\s*evasion", "antivirus\\s*evasion", "evade", "n[eé]\\s*tr[áa]nh.*(av|diệt virus)", "bypass.*(av|defender|edr)"], "explanation": "AV evasion (né tránh antivirus/EDR) là tập kỹ thuật (đóng gói lại, obfuscation, mã hóa, thay đổi chữ ký...) nhằm khiến payload không bị công cụ bảo mật như Windows Defender nhận diện là độc hại.", "hint": "Mục tiêu là làm cho payload ''vô hình'' trước phần mềm diệt virus."}, {"prompt": "Một kỹ thuật phổ biến để tránh bị phát hiện theo chữ ký (signature) là biến đổi mã nguồn/payload (đổi tên biến, chèn mã rác, mã hóa chuỗi...) sao cho chức năng giữ nguyên nhưng ''hình dạng'' của file thay đổi. Kỹ thuật này tên là gì?", "patterns": ["obfuscat", "obfuscation", "l[àa]m\\s*r[ốô]i"], "explanation": "Obfuscation (làm rối mã) thay đổi cách payload trông như thế nào (cấu trúc, tên biến, chuỗi mã hóa...) mà không đổi hành vi thực thi, giúp vượt qua việc phát hiện dựa trên chữ ký tĩnh (static signature).", "hint": "Kỹ thuật này làm mã nguồn trở nên khó đọc/khó nhận diện hơn, nhưng chức năng không đổi."}, {"prompt": "Sau khi có shell trên máy Windows bị kiểm soát, để duy trì quyền truy cập sau khi máy khởi động lại (reboot) hoặc người dùng đăng xuất, kẻ tấn công thường thiết lập cơ chế gì để tự động chạy lại payload?", "patterns": ["persistence", "duy\\s*tr[ìi]", "scheduled\\s*task", "registry\\s*run\\s*key", "startup"], "explanation": "Persistence (duy trì truy cập) là việc cài đặt payload vào các cơ chế tự chạy của hệ thống như Scheduled Task, Registry Run key hoặc Startup folder, để vẫn giữ được shell sau khi máy khởi động lại.", "hint": "Mục tiêu là giữ được quyền truy cập dù máy có tắt/mở lại."}, {"prompt": "Nếu payload chạy với quyền người dùng thông thường nhưng cần quyền Administrator đầy đủ trên Windows, kẻ tấn công có thể cố gắng vượt qua cơ chế cảnh báo cấp quyền của Windows. Cơ chế đó (và kỹ thuật vượt qua nó) thường được gọi là gì?", "patterns": ["uac", "user\\s*account\\s*control"], "explanation": "UAC (User Account Control) là cơ chế của Windows yêu cầu xác nhận khi một tiến trình muốn nâng quyền. ''UAC bypass'' là các kỹ thuật lợi dụng tiến trình tin cậy hoặc registry để nâng quyền mà không hiện hộp thoại xác nhận.", "hint": "Tên viết tắt 3 chữ của cơ chế kiểm soát nâng quyền trên Windows."}], "difficulty": "trung_binh", "cert_tags": ["THM PT1"], "challenge_key": "THM:Stealth"}'),
  ('[Simulation] THM — Loopback', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Loopback\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Sau khi quét toàn bộ cổng bằng nmap và thấy các cổng HTTP/HTTPS cùng RDP đang mở, bước tiếp theo để tìm các đường dẫn/thư mục ẩn trên web server (ví dụ phát hiện ra đường dẫn /ecp của Exchange) là dùng loại công cụ gì?", "patterns": ["gobuster", "dirbuster", "ffuf", "dirb", "directory\\s*(brute|fuzz)"], "explanation": "Gobuster (hoặc ffuf/dirbuster) dùng để brute-force các đường dẫn/thư mục ẩn trên web server bằng wordlist, giúp phát hiện các endpoint quản trị như /ecp (Exchange Control Panel) mà không được liệt kê công khai.", "hint": "Công cụ dò thư mục web bằng wordlist, thường dùng cùng SecLists."}, {"prompt": "Đường dẫn /ecp là dấu hiệu đặc trưng của một ứng dụng mail server phổ biến của Microsoft. Ứng dụng đó tên là gì?", "patterns": ["exchange", "microsoft\\s*exchange", "owa"], "explanation": "/ecp (Exchange Control Panel) và /owa (Outlook Web Access) là các endpoint đặc trưng của Microsoft Exchange Server, một mục tiêu phổ biến cho các lỗ hổng pre-auth RCE nổi tiếng.", "hint": "Đây là phần mềm email server của Microsoft, nổi tiếng với lỗ hổng ProxyShell/ProxyLogon."}, {"prompt": "Một tính năng trên web portal (ví dụ liên quan BitLocker) cho phép nhập đường dẫn, nhưng ứng dụng không lọc kỹ đầu vào nên kẻ tấn công có thể chèn thêm lệnh hệ thống (ví dụ dir, type) để thực thi trên server. Lớp lỗ hổng này gọi là gì?", "patterns": ["command\\s*injection", "os\\s*command\\s*injection", "ch[èe]n\\s*l[ệe]nh"], "explanation": "Command injection (chèn lệnh hệ thống) xảy ra khi input của người dùng được nối trực tiếp vào lệnh shell/PowerShell mà không được validate, cho phép kẻ tấn công thực thi lệnh tùy ý như liệt kê thư mục hoặc đọc file.", "hint": "Lỗ hổng cho phép chạy thêm lệnh OS thông qua một trường input của web app."}, {"prompt": "Khi đã xác định Exchange Server có khả năng chưa cập nhật bản vá, kẻ tấn công tìm kiếm một chuỗi khai thác pre-authentication nổi tiếng (CVE-2021-34473 và liên quan) cho phép thực thi mã từ xa trên Exchange mà không cần đăng nhập. Chuỗi khai thác này tên là gì?", "patterns": ["proxyshell", "cve-?2021-?34473"], "explanation": "ProxyShell là chuỗi lỗ hổng (gồm CVE-2021-34473 và các CVE liên quan) trên Microsoft Exchange cho phép remote code execution pre-auth, thường được khai thác qua module Metasploit có sẵn để lấy shell với quyền SYSTEM.", "hint": "Tên lỗ hổng bắt đầu bằng ''Proxy'', nổi tiếng trên Exchange Server năm 2021."}], "difficulty": "trung_binh", "cert_tags": ["THM PT1"], "challenge_key": "THM:Loopback"}'),
  ('[Simulation] THM — NahamStore', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"NahamStore\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Để tìm ra các subdomain ẩn của một website (ví dụ shop., marketing., stock.) khi không có DNS public, người ta có thể fuzz giá trị header Host trong HTTP request với một wordlist, rồi lọc theo kích thước response khác với response mặc định. Công cụ fuzzing phổ biến dùng cho kỹ thuật này là gì?", "patterns": ["wfuzz", "ffuf", "gobuster\\s*vhost"], "explanation": "Wfuzz (hoặc ffuf với chế độ vhost) cho phép thay đổi header Host theo một wordlist và lọc kết quả theo kích thước response, giúp phát hiện các virtual host/subdomain ẩn không được liệt kê công khai.", "hint": "Công cụ fuzz HTTP request, có thể thay đổi header Host theo wordlist."}, {"prompt": "Khi nhập một payload script vào ô tìm kiếm hoặc tham số URL và thấy nó được phản chiếu ngay lại trong trang kết quả (không lưu trữ), đây là loại lỗ hổng XSS nào?", "patterns": ["reflected\\s*xss"], "explanation": "Reflected XSS xảy ra khi input từ URL/tham số được đưa thẳng vào HTML response mà không mã hóa, và payload chỉ ảnh hưởng ngay trong request đó, không được lưu lại cho người dùng khác.", "hint": "Payload xuất hiện ngay trong response của chính request đó, không lưu vào database."}, {"prompt": "Nếu payload XSS được chèn vào trường User-Agent khi đặt hàng, và sau đó payload này được admin xem lại (ví dụ trong trang quản lý đơn hàng) và tự động thực thi, đây là loại XSS nào?", "patterns": ["stored\\s*xss", "persistent\\s*xss"], "explanation": "Stored XSS (hay persistent XSS) là khi payload độc hại được lưu vào server (database, log...) và thực thi lại mỗi khi một người dùng khác (ví dụ admin) xem lại dữ liệu đó, nguy hiểm hơn reflected XSS vì ảnh hưởng nhiều người dùng.", "hint": "Payload được lưu vào hệ thống (ví dụ header User-Agent của đơn hàng) và chạy lại khi người khác xem."}, {"prompt": "Khi thay đổi giá trị address_id hoặc user_id trong URL để xem được địa chỉ/đơn hàng của người dùng khác (không phải của mình), lớp lỗ hổng kiểm soát truy cập này tên là gì?", "patterns": ["idor", "insecure\\s*direct\\s*object"], "explanation": "IDOR (Insecure Direct Object Reference) xảy ra khi ứng dụng dùng ID do người dùng kiểm soát (address_id, user_id...) để truy xuất dữ liệu mà không kiểm tra quyền sở hữu, cho phép truy cập dữ liệu của người dùng khác.", "hint": "Viết tắt 4 chữ, liên quan đến việc tham chiếu trực tiếp object qua ID mà không kiểm tra quyền."}, {"prompt": "Một endpoint tải ảnh dùng tham số file= để chỉ định file cần đọc, có bộ lọc chặn chuỗi ''../'' nhưng có thể bị vượt qua bằng cách lồng nhiều lần ký tự traversal. Lớp lỗ hổng cho phép đọc file tùy ý trên server qua kiểu tham số file= này gọi là gì?", "patterns": ["lfi", "local\\s*file\\s*inclusion", "path\\s*traversal", "directory\\s*traversal"], "explanation": "LFI (Local File Inclusion) / Path Traversal cho phép đọc file tùy ý trên server thông qua tham số đường dẫn (ví dụ file=../../etc/passwd); nếu bộ lọc chỉ xóa ''../'' một lần, chuỗi như ''....//'' sau khi lọc vẫn còn lại ''../'' để vượt qua filter.", "hint": "Lỗ hổng liên quan đến tham số file=, cho phép đọc file ngoài thư mục dự kiến bằng dấu ../ lồng nhau."}], "difficulty": "trung_binh", "cert_tags": ["THM PT1", "THM WEB1"], "challenge_key": "THM:NahamStore"}'),
  ('[Simulation] THM — Sweettooth Inc.', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Sweettooth Inc.\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Sau khi quét toàn bộ cổng TCP, một dịch vụ cơ sở dữ liệu time-series phiên bản cũ (có lỗ hổng authentication bypass công khai) được phát hiện chạy ở một cổng không chuẩn. Tên loại database đó là gì?", "patterns": ["influxdb"], "explanation": "InfluxDB là database time-series; phiên bản 1.3.0 trong writeup có lỗ hổng authentication bypass đã công bố công khai, cho phép giả mạo xác thực mà không cần biết mật khẩu thật.", "hint": "Đây là một database chuyên lưu dữ liệu theo thời gian (time-series), tên bắt đầu bằng ''Influx''."}, {"prompt": "Lỗ hổng cho phép tạo một token xác thực giả (ví dụ dùng jwt.io với secret để trống và username bị lộ qua endpoint debug) để được InfluxDB chấp nhận như đã đăng nhập hợp lệ. Loại token/kỹ thuật giả mạo xác thực này gọi là gì?", "patterns": ["jwt", "json\\s*web\\s*token", "auth(entication)?\\s*bypass"], "explanation": "JWT (JSON Web Token) forgery: khi secret dùng để ký token để trống hoặc dễ đoán, kẻ tấn công có thể tự tạo (forge) một JWT hợp lệ với username lấy được từ endpoint rò rỉ thông tin, qua đó bypass xác thực của InfluxDB.", "hint": "Đây là loại token JSON dùng để xác thực API, có thể bị giả mạo nếu secret ký yếu hoặc rỗng."}, {"prompt": "Sau khi có quyền truy cập SSH vào container và phát hiện Docker Engine API đang lắng nghe cục bộ (ví dụ cổng 8080), kẻ tấn công tạo một container mới có bind-mount toàn bộ filesystem gốc của host vào trong, rồi exec để chạy shell với quyền privileged. Kỹ thuật này gọi là gì?", "patterns": ["container\\s*escape", "docker\\s*escape", "privileged\\s*container"], "explanation": "Đây là kỹ thuật container escape qua Docker Engine API: bằng cách tạo container mới bind-mount ''/'' của host và chạy ở chế độ privileged, kẻ tấn công thoát ra khỏi container ban đầu và có toàn quyền đọc/ghi trên hệ thống host.", "hint": "Kỹ thuật này giúp ''thoát'' khỏi container Docker để chiếm quyền trên máy chủ thật (host)."}], "difficulty": "trung_binh", "cert_tags": ["THM WEB1"], "challenge_key": "THM:Sweettooth Inc."}'),
  ('[Simulation] THM — Gotta Catch''em All', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Gotta Catch''em All\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Trước khi quét port, một bước đơn giản nhưng hữu ích là xem mã nguồn (view source) của trang mặc định Apache đang hiển thị, vì đôi khi nhà phát triển để lại comment hoặc gợi ý trong đó. Kỹ thuật này gọi tổng quát là gì?", "patterns": ["view\\s*source", "source\\s*code\\s*review", "xem\\s*m[ãa]\\s*ngu[ồô]n"], "explanation": "Xem mã nguồn HTML (view-source) của trang web là một bước enumeration cơ bản, có thể để lộ comment, đường dẫn ẩn hoặc gợi ý do nhà phát triển vô tình để lại.", "hint": "Trong browser có thể bấm chuột phải để xem HTML gốc của trang."}, {"prompt": "Sau khi có được thông tin đăng nhập (ví dụ từ gợi ý trên trang web), bạn đăng nhập vào máy chủ qua một dịch vụ remote shell phổ biến chạy trên cổng 22. Tên dịch vụ đó là gì?", "patterns": ["ssh"], "explanation": "SSH (Secure Shell) là dịch vụ đăng nhập remote shell được mã hóa, thường chạy ở cổng 22, cho phép truy cập dòng lệnh trên máy chủ từ xa khi có thông tin đăng nhập hợp lệ.", "hint": "Dịch vụ remote shell mã hóa, thường ở cổng 22."}, {"prompt": "Trong quá trình tìm các file (ví dụ các file ''grass'', ''water'', ''fire'' theo chủ đề Pokemon) rải rác trong hệ thống file, lệnh Linux nào thường dùng để tìm file theo tên trên toàn bộ hoặc một phần cây thư mục?", "patterns": ["\\bfind\\b"], "explanation": "Lệnh `find` cho phép tìm kiếm file theo tên, loại, quyền... trên toàn bộ hệ thống file, rất hữu ích khi cần định vị các file được giấu ở nhiều thư mục khác nhau trong quá trình post-exploitation.", "hint": "Lệnh Linux cơ bản để tìm file theo tên, ví dụ: find / -name \"*.txt\"."}, {"prompt": "Một số file thu được chứa dữ liệu được mã hóa dạng hex, ROT13/ROT14 hoặc base64. Công cụ web (và cũng có bản offline) rất phổ biến để giải mã nhanh nhiều loại encoding/cipher khác nhau chỉ bằng cách kéo-thả các bước xử lý là gì?", "patterns": ["cyberchef"], "explanation": "CyberChef là công cụ ''dao đa năng'' cho việc mã hóa/giải mã, hỗ trợ rất nhiều định dạng như hex, base64, ROT13/ROT-N, cho phép xếp chuỗi nhiều bước xử lý (recipe) để giải mã dữ liệu phức tạp.", "hint": "Công cụ web được gọi là ''con dao quân đội Thụy Sĩ'' của mã hóa/giải mã dữ liệu."}, {"prompt": "Sau khi tìm thấy thông tin đăng nhập của một người dùng khác trong một file cấu hình/source code, bạn dùng lệnh gì để chuyển sang người dùng đó (horizontal privilege escalation) mà không cần đăng xuất SSH?", "patterns": ["\\bsu\\b", "su\\s*-"], "explanation": "Lệnh `su <username>` cho phép chuyển sang một người dùng khác ngay trong session hiện tại khi có mật khẩu của họ, thường dùng trong leo quyền ngang (horizontal privilege escalation) sau khi tìm được credential bị lộ.", "hint": "Lệnh Linux 2 chữ để chuyển sang người dùng khác, viết tắt của ''substitute user''."}], "difficulty": "trung_binh", "cert_tags": ["THM PT1"], "challenge_key": "THM:Gotta Catch''em All"}'),
  ('[Simulation] THM — AD Basic Enumeration', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"AD Basic Enumeration\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Trước khi quét port chi tiết, bạn cần xác định các máy đang sống (live hosts) trong một subnet nội bộ của Active Directory. Công cụ dòng lệnh nhanh dùng ICMP để quét nhiều host đồng thời (ping sweep) là gì?", "patterns": ["fping", "nmap\\s*-sn", "ping\\s*sweep"], "explanation": "fping (hoặc nmap -sn) cho phép quét ping một dải IP lớn nhanh hơn ping tuần tự, giúp xác định các máy đang hoạt động (live hosts) trước khi quét port chi tiết hơn vào từng máy.", "hint": "Công cụ này là phiên bản ''ping song song'' cho nhiều địa chỉ IP cùng lúc."}, {"prompt": "Khi liệt kê các share SMB trên Domain Controller mà không cần thông tin đăng nhập (username và password để trống), kỹ thuật này gọi là gì?", "patterns": ["null\\s*session", "anonymous\\s*(bind|login|access)", "smbclient\\s*-n"], "explanation": "Null session (hoặc anonymous access) là việc kết nối SMB/RPC/LDAP mà không cung cấp username/password hợp lệ (dùng -N hoặc user rỗng); nhiều AD cấu hình sai vẫn cho phép liệt kê share, user hoặc policy qua null session.", "hint": "Kỹ thuật kết nối SMB mà không cần username/password, dùng cờ -N với smbclient."}, {"prompt": "Để kết nối và liệt kê toàn bộ user trong domain qua RPC bằng null session (ví dụ lệnh enumdomusers), công cụ dòng lệnh nào thường được dùng?", "patterns": ["rpcclient"], "explanation": "rpcclient cho phép kết nối tới dịch vụ RPC của Domain Controller (có thể dùng null session với -U \"\" -N) và chạy các lệnh như enumdomusers để liệt kê toàn bộ user trong domain, hoặc getdompwinfo để xem chính sách mật khẩu.", "hint": "Công cụ bắt đầu bằng ''rpc'', dùng để tương tác với dịch vụ RPC của Windows/Samba."}, {"prompt": "Sau khi có danh sách username và biết chính sách mật khẩu (độ dài tối thiểu, độ phức tạp, số lần khóa tài khoản), bạn thử một vài mật khẩu phổ biến cho MỖI user (chỉ 1-2 lần/user) để tránh bị khóa tài khoản. Kỹ thuật tấn công đăng nhập này gọi là gì?", "patterns": ["password\\s*spray(ing)?", "phun\\s*m[ậa]t\\s*kh[ẩẩ]u", "x[ịi]t\\s*m[ậa]t\\s*kh[ẩẩ]u"], "explanation": "Password spraying là kỹ thuật thử một hoặc vài mật khẩu phổ biến trên NHIỀU tài khoản, mỗi tài khoản chỉ thử rất ít lần, nhằm tránh vượt ngưỡng khóa tài khoản (lockout threshold) mà brute-force truyền thống (nhiều mật khẩu trên 1 user) dễ gây ra.", "hint": "Khác với brute-force 1 user nhiều mật khẩu, kỹ thuật này thử ít mật khẩu nhưng trên nhiều user để tránh lockout."}, {"prompt": "Công cụ nào thường dùng để kiểm tra chính sách mật khẩu domain qua SMB (ví dụ chạy với tùy chọn --pass-pol) và cũng hỗ trợ thực hiện password spraying hàng loạt trên nhiều máy Windows/AD?", "patterns": ["crackmapexec", "cme", "netexec", "nxc"], "explanation": "CrackMapExec (hoặc bản kế nhiệm NetExec) là công cụ post-exploitation cho AD, hỗ trợ lấy chính sách mật khẩu (--pass-pol), thực hiện password spraying, và nhiều tác vụ enumeration/khai thác khác trên mạng Windows.", "hint": "Công cụ pentest AD phổ biến, viết tắt thường gọi là CME (hoặc bản mới là NetExec/nxc)."}], "difficulty": "trung_binh", "cert_tags": ["THM PT1"], "challenge_key": "THM:AD Basic Enumeration"}'),
  ('[Simulation] THM — RabbitStore', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"RabbitStore\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Trong lúc rà soát ứng dụng web ở mức SSRF, bạn có một tính năng server tự tải nội dung từ một URL do người dùng cung cấp (upload-from-URL hoặc tương tự). Kỹ thuật nào cho phép bạn dùng chính tính năng này để dò các cổng dịch vụ đang chạy trên <IP> nội bộ (localhost) mà bạn không thể truy cập trực tiếp?", "patterns": ["ssrf", "server[- ]side request forgery"], "explanation": "Đây là lỗ hổng SSRF (Server-Side Request Forgery): server bị lừa gửi request thay cho attacker tới các địa chỉ nội bộ, qua đó có thể dùng để port-scan hoặc truy cập dịch vụ chỉ lắng nghe trên localhost.", "hint": "Lỗ hổng khiến server gửi request tới nơi attacker chỉ định, thường dùng để quét mạng nội bộ."}, {"prompt": "Khi đăng ký tài khoản, request gửi lên server có thêm một trường không được hiển thị trên giao diện (ví dụ trường trạng thái gói đăng ký) và server vẫn chấp nhận giá trị đó, giúp bạn có quyền truy cập cao hơn dự kiến. Đây là loại lỗ hổng gì?", "patterns": ["mass assignment", "over[- ]?posting", "parameter pollution"], "explanation": "Đây là lỗi Mass Assignment: backend tự động gán toàn bộ các trường trong request vào object dữ liệu mà không kiểm soát whitelist trường nào được phép người dùng chỉnh.", "hint": "Lỗi liên quan đến việc server nhận và gán luôn mọi trường trong JSON/form request vào model, kể cả trường nhạy cảm."}, {"prompt": "Một chatbot trong ứng dụng render trực tiếp input của người dùng vào một template engine (ví dụ Jinja2). Bạn gửi một biểu thức toán học để kiểm tra xem server có tính toán và trả kết quả không, sau đó khai thác để thực thi lệnh hệ thống. Kỹ thuật/lớp lỗ hổng này tên là gì?", "patterns": ["ssti", "server[- ]side template injection", "jinja"], "explanation": "Đây là Server-Side Template Injection (SSTI): input người dùng được render trực tiếp bởi template engine phía server, cho phép thực thi mã (RCE) nếu không được sanitize.", "hint": "Tên lỗ hổng khi input được template engine phía server thực thi như code, viết tắt 3 chữ."}, {"prompt": "Sau khi chiếm được shell với quyền user thấp, bạn phát hiện file cookie xác thực của broker message queue (ví dụ Erlang cookie của RabbitMQ) có quyền đọc cho user hiện tại. Cookie này có thể bị lợi dụng để làm gì nhằm chiếm quyền của service account chạy broker?", "patterns": ["erlang cookie", "rce", "distribution protocol", "remote code execution"], "explanation": "Erlang cookie dùng để xác thực giữa các node trong Erlang distribution protocol; nếu đọc được cookie, attacker có thể kết nối tới node Erlang (ví dụ của RabbitMQ) và thực thi lệnh với quyền của service đó.", "hint": "File xác thực giữa các node Erlang, nếu lộ ra có thể dùng để chạy lệnh từ xa trên node đó."}, {"prompt": "Sau khi có quyền quản trị RabbitMQ, bạn dùng API quản trị HTTP của RabbitMQ để lấy danh sách user, trong đó có password hash của user root được lưu ở dạng base64 chứa salt + hash. Để lấy được giá trị hash chuẩn (ví dụ SHA-256) từ dữ liệu này, bạn cần thực hiện bước xử lý nào?", "patterns": ["base64", "decode", "hex", "salt"], "explanation": "Cần decode chuỗi base64 thành dữ liệu hex/binary, sau đó loại bỏ phần salt ở đầu để lấy đúng giá trị hash chuẩn có thể tra cứu hoặc so khớp.", "hint": "Liên quan tới việc giải mã base64 rồi cắt bỏ phần salt phía trước hash."}], "difficulty": "nang_cao", "cert_tags": ["THM PT1", "THM WEB1"], "challenge_key": "THM:RabbitStore"}'),
  ('[Simulation] THM — Billing', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Billing\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Khi quét thư mục web không ra kết quả hữu ích, bạn kiểm tra file robots.txt và phát hiện một đường dẫn dẫn tới ứng dụng billing VoIP (MagnusBilling) đang chạy. Việc kiểm tra robots.txt để tìm đường dẫn ẩn là một kỹ thuật gì trong giai đoạn enumeration web?", "patterns": ["robots\\.txt", "enumeration", "directory discovery"], "explanation": "robots.txt thường do nhà phát triển dùng để chặn search engine index một số thư mục, nhưng lại vô tình tiết lộ các đường dẫn nội bộ hữu ích cho việc enumeration.", "hint": "Một file text chuẩn cho search engine, nhưng có thể để lộ đường dẫn ẩn."}, {"prompt": "Bạn xác định ứng dụng billing đang chạy có một mã CVE công khai cho phép thực thi lệnh từ xa không cần xác thực (unauthenticated RCE). Công cụ khai thác tự động nào thường được dùng để tìm và chạy module khai thác sẵn có cho CVE như vậy?", "patterns": ["metasploit", "msfconsole"], "explanation": "Metasploit Framework chứa sẵn nhiều module khai thác cho các CVE phổ biến; chỉ cần set đúng target, RHOSTS và các option rồi chạy exploit để lấy shell.", "hint": "Framework khai thác nổi tiếng với các module exploit có sẵn, dùng msfconsole."}, {"prompt": "Sau khi có shell với quyền thấp, bạn chạy lệnh để kiểm tra user hiện tại có quyền chạy chương trình nào với sudo mà không cần mật khẩu. Lệnh đó là gì?", "patterns": ["sudo -l", "sudo l"], "explanation": "`sudo -l` liệt kê các lệnh user hiện tại được phép chạy bằng sudo, đây là bước kiểm tra privilege escalation kinh điển trên Linux.", "hint": "Lệnh sudo với flag viết thường ''l'' để liệt kê quyền."}, {"prompt": "Bạn phát hiện user được phép chạy fail2ban-client bằng sudo không cần mật khẩu. Fail2Ban cho phép cấu hình ''action'' tùy chỉnh chạy khi một IP bị ban. Kỹ thuật lợi dụng tính năng này để chạy lệnh với quyền root được gọi là gì?", "patterns": ["fail2ban", "custom action", "ban action abuse"], "explanation": "Fail2Ban chạy các action (thường là shell command) với quyền root khi một jail kích hoạt ban; nếu attacker có quyền sửa cấu hình action, họ có thể chèn lệnh tùy ý để thực thi với quyền root khi ban được trigger.", "hint": "Liên quan tới việc sửa action của jail (ví dụ sshd) trong Fail2Ban để chạy lệnh tùy chỉnh."}], "difficulty": "nang_cao", "cert_tags": ["THM PT1"], "challenge_key": "THM:Billing"}'),
  ('[Simulation] THM — Silver Platter', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Silver Platter\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Bạn phát hiện một ứng dụng web chạy trên cổng không chuẩn (ví dụ 8080) với trang đăng nhập riêng. Nghiên cứu CVE cho ứng dụng này, bạn tìm thấy một lỗ hổng cho phép bỏ qua xác thực chỉ bằng cách bỏ (omit) một tham số cụ thể trong request đăng nhập. Loại lỗ hổng này được gọi là gì?", "patterns": ["authentication bypass", "auth bypass", "login bypass"], "explanation": "Đây là lỗ hổng Authentication Bypass: do xử lý logic sai ở server, việc thiếu một tham số (ví dụ password) trong request khiến server coi như đăng nhập hợp lệ.", "hint": "Lỗ hổng cho phép đăng nhập mà không cần đúng thông tin xác thực, do thiếu kiểm tra tham số."}, {"prompt": "Sau khi có session hợp lệ, bạn truy cập một module tin nhắn nội bộ và bằng cách đổi ID trong URL/API, bạn đọc được tin nhắn của user khác (chứa thông tin đăng nhập). Loại lỗ hổng cho phép truy cập dữ liệu của người khác chỉ bằng cách đổi ID này gọi là gì?", "patterns": ["idor", "insecure direct object reference"], "explanation": "Đây là IDOR (Insecure Direct Object Reference): hệ thống không kiểm tra quyền sở hữu đối tượng, chỉ dựa vào ID do client gửi lên để trả dữ liệu.", "hint": "Viết tắt 4 chữ, liên quan đến việc đổi ID object để truy cập dữ liệu không thuộc về mình."}, {"prompt": "Một hướng khai thác khác là brute-force mật khẩu đăng nhập. Bạn dùng công cụ sinh wordlist từ nội dung văn bản trên chính trang web mục tiêu, sau đó dùng công cụ fuzzing HTTP để thử các mật khẩu đó vào endpoint đăng nhập, lọc kết quả theo độ dài response. Tên hai công cụ này là gì?", "patterns": ["cewl", "ffuf"], "explanation": "CeWL tạo wordlist tùy biến từ nội dung text của website (thường chứa từ ngữ đặc trưng của tổ chức), còn ffuf dùng để fuzz các giá trị đó vào request đăng nhập và phân biệt thành công/thất bại qua kích thước response.", "hint": "Một công cụ sinh wordlist từ web content, một công cụ fuzzing HTTP nhanh viết bằng Go."}, {"prompt": "Ở bước privilege escalation, bạn phát hiện user thấp quyền thuộc group ''adm'', cho phép đọc log hệ thống trong /var/log. Tìm kiếm từ khóa nhạy cảm trong log, bạn phát hiện một dòng lệnh chứa mật khẩu database của user khác bị log lại. Kỹ thuật này gọi là gì?", "patterns": ["log.*(credential|password)", "sensitive.*log", "command.*history.*leak", "log analysis"], "explanation": "Đây là kỹ thuật rò rỉ thông tin nhạy cảm qua log hệ thống: các lệnh chứa mật khẩu trong tham số dòng lệnh có thể bị ghi vào log (ví dụ log của auth, process accounting) và lộ ra cho ai đọc được log.", "hint": "Liên quan đến việc mật khẩu vô tình bị ghi lại trong log do được truyền qua command-line."}], "difficulty": "nang_cao", "cert_tags": ["THM PT1"], "challenge_key": "THM:Silver Platter"}'),
  ('[Simulation] THM — Avenger', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Avenger\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Bạn có danh sách tên nhân viên thật của tổ chức và muốn sinh ra các username khả dĩ theo quy ước đặt tên doanh nghiệp phổ biến (ví dụ tên.họ, họ_tên viết tắt), sau đó xác thực từng username với dịch vụ Kerberos để biết username nào thật sự tồn tại trong domain. Công cụ dùng để xác thực username qua Kerberos theo cách này gọi là gì?", "patterns": ["kerbrute"], "explanation": "Kerbrute cho phép kiểm tra username hợp lệ bằng cách gửi yêu cầu pre-authentication Kerberos (AS-REQ) và quan sát phản hồi khác nhau giữa username tồn tại và không tồn tại, không cần biết mật khẩu.", "hint": "Công cụ chuyên dò username hợp lệ qua giao thức Kerberos."}, {"prompt": "Sau khi xác thực được domain user bằng mật khẩu tái sử dụng từ máy khác, bạn muốn thu thập toàn bộ cấu trúc quan hệ, nhóm và quyền trong Active Directory (ai có quyền gì trên ai) để tìm đường leo thang. Công cụ/kỹ thuật chuyên dùng để visualize và phân tích quan hệ AD này là gì?", "patterns": ["bloodhound"], "explanation": "BloodHound (thu thập dữ liệu bằng bloodhound-python hoặc SharpHound) dựng đồ thị quan hệ AD, giúp phát hiện các đường leo thang quyền như quyền GenericAll, DCSync, thành viên nhóm lồng nhau.", "hint": "Công cụ dựng đồ thị quan hệ Active Directory để tìm đường leo thang quyền."}, {"prompt": "BloodHound cho thấy user bạn đang chiếm giữ có quyền GenericAll trên một tài khoản khác trong AD. Quyền này cho phép bạn làm gì trực tiếp với tài khoản mục tiêu để chiếm quyền của nó, ví dụ qua lệnh net rpc?", "patterns": ["reset.*password", "genericall", "change password"], "explanation": "Quyền GenericAll trên một object AD cho phép toàn quyền chỉnh sửa object đó, bao gồm đặt lại (reset) mật khẩu của tài khoản mục tiêu mà không cần biết mật khẩu cũ, từ đó đăng nhập được với quyền của nó.", "hint": "Một quyền AD cho toàn quyền trên object, thường bị lợi dụng để đặt lại mật khẩu tài khoản khác."}, {"prompt": "Bạn phát hiện user hiện tại có quyền đặc biệt SeBackupPrivilege/SeRestorePrivilege trên Windows. Lợi dụng quyền này, bạn tạo shadow copy của ổ C: rồi copy file ntds.dit (database AD) cùng SYSTEM hive ra ngoài để trích xuất offline. Công cụ Windows dùng để tạo và mount shadow copy trong kỹ thuật này gọi là gì?", "patterns": ["diskshadow"], "explanation": "diskshadow là công cụ built-in của Windows để tạo volume shadow copy; kết hợp với robocopy ở chế độ backup, nó cho phép copy file ntds.dit đang bị khóa để trích xuất hash offline.", "hint": "Công cụ built-in Windows để tạo và quản lý Volume Shadow Copy."}, {"prompt": "Sau khi lấy được ntds.dit và SYSTEM hive, bạn dùng công cụ nào (thuộc bộ Impacket) để trích xuất offline toàn bộ NTLM hash của các tài khoản domain, bao gồm cả Administrator?", "patterns": ["secretsdump"], "explanation": "secretsdump.py của Impacket có thể phân tích ntds.dit cùng SYSTEM hive để dump toàn bộ NTLM hash của domain mà không cần đăng nhập trực tiếp vào DC.", "hint": "Script trong bộ Impacket chuyên dump hash từ ntds.dit/SAM/SYSTEM."}], "difficulty": "nang_cao", "cert_tags": ["THM PT1"], "challenge_key": "THM:Avenger"}'),
  ('[Simulation] THM — Lateral Movement and Pivoting', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Lateral Movement and Pivoting\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Bạn có quyền truy cập SSH vào một máy trung gian (pivot host) và muốn mở một proxy SOCKS động trên máy của mình để định tuyến traffic của các công cụ khác (như nmap, curl) vào mạng nội bộ phía sau pivot. Flag SSH nào dùng để tạo dynamic port forwarding như vậy, và công cụ nào thường kết hợp để route traffic của tool khác qua proxy đó?", "patterns": ["ssh -d", "dynamic forwarding", "proxychains"], "explanation": "SSH với flag `-D <port>` tạo một SOCKS proxy động trên máy local; kết hợp với proxychains, các công cụ không hỗ trợ proxy trực tiếp vẫn có thể được route traffic qua pivot host vào mạng nội bộ.", "hint": "Một flag SSH mở SOCKS proxy, thường dùng cùng công cụ ''proxychains''."}, {"prompt": "Khi dùng proxychains để quét cổng trên mạng nội bộ qua pivot, bạn gặp giới hạn: không scan được bằng SYN scan, không ping được bằng ICMP. Flag nmap nào cần thêm để bỏ qua bước ping trước khi scan, cho phù hợp với giới hạn TCP-only của proxychains?", "patterns": ["-pn", "no ping"], "explanation": "proxychains chỉ hỗ trợ traffic TCP (connect scan), không hỗ trợ ICMP hay raw socket cho SYN scan; vì vậy cần dùng `-Pn` để nmap bỏ qua host-discovery bằng ping và chạy TCP connect scan (-sT) thay vì -sS.", "hint": "Flag nmap để bỏ qua bước ping trước khi quét cổng."}, {"prompt": "Bạn không có quyền SSH trên host bị chiếm nhưng có thể copy một binary nhỏ gọn lên đó để tạo tunnel SOCKS ngược (reverse) về máy attacker, không cần cấu hình gì phức tạp trên target. Tên công cụ tunneling phổ biến, hỗ trợ cả Windows và Linux, thường dùng trong tình huống này là gì?", "patterns": ["chisel"], "explanation": "Chisel là công cụ tunneling hoạt động qua HTTP, không cần SSH, chỉ cần copy binary chisel lên cả hai máy; hỗ trợ chế độ reverse SOCKS (`R:socks`) để mở proxy trên máy attacker thông qua kết nối ngược từ target.", "hint": "Công cụ tunneling không cần SSH, có cả bản Windows và Linux, hỗ trợ reverse SOCKS."}, {"prompt": "Một công cụ khác hoạt động như VPN trong suốt (transparent), chỉ cần Python và quyền SSH trên remote host, không cần quyền admin, nhưng lại không hỗ trợ chạy nmap qua nó. Tên công cụ này là gì?", "patterns": ["sshuttle"], "explanation": "sshuttle tạo một kênh giống VPN qua SSH, route toàn bộ traffic tới một subnet chỉ định qua pivot host, nhưng do cách hoạt động của nó (viết lại traffic ở mức transport), các công cụ dùng raw socket như nmap thường không chạy được qua nó.", "hint": "Công cụ pivoting giống VPN, cần Python + SSH trên remote host, không hỗ trợ nmap."}, {"prompt": "Trong Meterpreter, khi bạn đã có một session trên máy pivot và muốn chạy exploit nhắm vào một dịch vụ (ví dụ cổng 445) trên mạng phía sau nó qua chính session này, bạn cần cấu hình route/relay rồi đặt giá trị RHOST của module exploit là gì?", "patterns": ["127\\.0\\.0\\.1", "localhost"], "explanation": "Khi dùng route/portfwd qua một Meterpreter session để relay traffic, các module exploit trong Metasploit cần đặt RHOST là 127.0.0.1 (localhost) vì traffic sẽ được Meterpreter session chuyển tiếp tới target thật ở phía sau.", "hint": "Địa chỉ loopback, vì traffic được relay qua chính session Meterpreter."}], "difficulty": "nang_cao", "cert_tags": ["THM PT1"], "challenge_key": "THM:Lateral Movement and Pivoting"}'),
  ('[Simulation] THM — K2', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"K2\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Trong giai đoạn đầu enumeration, bạn chạy một công cụ quét cổng nhanh (nhanh hơn nmap mặc định) để phát hiện toàn bộ cổng mở trước khi chạy nmap với các script chi tiết (-A -sC). Tên công cụ quét cổng nhanh này thường dùng kết hợp với nmap là gì?", "patterns": ["rustscan"], "explanation": "RustScan quét toàn bộ 65535 cổng rất nhanh bằng cách tận dụng xử lý song song, sau đó có thể pipe kết quả cổng mở sang nmap để chạy script version/vulnerability detection chi tiết hơn.", "hint": "Công cụ quét cổng viết bằng Rust, nổi tiếng về tốc độ, thường kết hợp pipe sang nmap."}, {"prompt": "Bạn phát hiện một đường dẫn web không load được, và qua phân tích hành vi lỗi, bạn nhận ra đây là do virtual host chưa được khai báo đúng. Bạn cần thêm mapping tên miền tới IP của host vào đâu trên máy attacker để site load được?", "patterns": ["/etc/hosts", "hosts file"], "explanation": "Khi web server dùng virtual host (nhiều domain trên một IP), DNS công khai không biết tên miền đó; cần thêm thủ công một dòng ánh xạ domain-IP vào file /etc/hosts trên máy attacker để trình duyệt/công cụ phân giải đúng.", "hint": "File cấu hình DNS cục bộ trên Linux để ánh xạ tên miền với IP."}, {"prompt": "Sau khi xác định site là WordPress, bạn dùng một công cụ chuyên dụng để enumerate plugin, theme và phiên bản, từ đó phát hiện plugin Forminator đang ở phiên bản cũ có lỗ hổng. Tên công cụ enumerate WordPress này là gì?", "patterns": ["wpscan"], "explanation": "WPScan là công cụ chuyên dùng để quét WordPress, phát hiện plugin/theme đã cài, phiên bản của chúng, và đối chiếu với database lỗ hổng công khai.", "hint": "Công cụ CLI chuyên biệt để quét site WordPress tìm plugin/theme lỗ hổng."}, {"prompt": "Plugin Forminator phiên bản cũ có lỗ hổng cho phép upload file với bất kỳ loại nào mà không bị chặn, thông qua form công khai không cần xác thực. Loại lỗ hổng này gọi là gì?", "patterns": ["arbitrary file upload", "unrestricted file upload", "unauthenticated.*upload"], "explanation": "Đây là lỗ hổng Arbitrary/Unrestricted File Upload: server không kiểm tra đúng loại file được phép upload, cho phép attacker tải lên file thực thi được (ví dụ web shell hoặc batch script) rồi kích hoạt nó.", "hint": "Lỗ hổng liên quan tới việc form upload không giới hạn loại file được chấp nhận."}, {"prompt": "Sau khi có web shell với quyền SYSTEM trên máy Windows, bạn dùng lệnh Windows nào để export (dump) registry hive SAM và SYSTEM ra file, nhằm sau đó trích xuất NTLM hash offline bằng Impacket secretsdump?", "patterns": ["reg save"], "explanation": "Lệnh `reg save` cho phép xuất một registry hive (ví dụ SAM, SYSTEM) ra file ngoài, sau đó các file này được dùng với secretsdump.py (offline mode) để trích xuất NTLM hash của các local account.", "hint": "Lệnh Windows built-in để lưu một registry hive ra file."}, {"prompt": "Có được NTLM hash của Administrator nhưng chưa crack được mật khẩu, bạn vẫn đăng nhập WinRM thành công bằng chính hash đó thay vì mật khẩu plaintext. Kỹ thuật xác thực này gọi là gì?", "patterns": ["pass[- ]the[- ]hash", "pth"], "explanation": "Pass-the-Hash (PtH) là kỹ thuật dùng NTLM hash để xác thực trực tiếp với dịch vụ hỗ trợ NTLM (như WinRM, SMB) mà không cần biết mật khẩu plaintext tương ứng.", "hint": "Kỹ thuật xác thực chỉ cần NTLM hash, không cần crack ra mật khẩu gốc."}], "difficulty": "nang_cao", "cert_tags": ["THM PT1"], "challenge_key": "THM:K2"}'),
  ('[Simulation] THM — Writing Pentest Reports', '{"mode": "challenge_sim", "scenario": "Tự luyện câu hỏi/đáp án riêng cho \"Writing Pentest Reports\" (THM) trước khi làm thật — không tính vào ôn tập ngắt quãng. Câu hỏi được soạn từ bài giải tham khảo, tập trung vào kỹ thuật/phương pháp (không phải flag cụ thể).", "steps": [{"prompt": "Một báo cáo pentest tốt phải phục vụ nhiều đối tượng đọc khác nhau: lãnh đạo doanh nghiệp (business), đội bảo mật, và đội kỹ thuật/dev. Phần nào của báo cáo thường được viết bằng ngôn ngữ phi kỹ thuật, tóm tắt những gì đã kiểm tra, phát hiện gì, tác động ra sao và bước tiếp theo?", "patterns": ["executive summary", "tóm tắt", "summary"], "explanation": "Phần Tóm tắt/Executive Summary trình bày ở mức cao, phi kỹ thuật, giúp các bên liên quan không chuyên về kỹ thuật (như quản lý, lãnh đạo) hiểu nhanh kết quả và mức độ rủi ro tổng thể của đợt kiểm tra.", "hint": "Phần báo cáo viết cho người đọc không chuyên kỹ thuật, nằm đầu báo cáo."}, {"prompt": "Mỗi lỗ hổng được ghi nhận trong báo cáo cần có một chỉ số định lượng mức độ nghiêm trọng để giúp đội bảo mật ưu tiên xử lý. Hệ thống tính điểm phổ biến dùng để xếp hạng mức độ nghiêm trọng của lỗ hổng là gì?", "patterns": ["cvss"], "explanation": "CVSS (Common Vulnerability Scoring System) cung cấp điểm số chuẩn hóa (ví dụ CVSS 3.1 base score) cùng mức nghiêm trọng (Critical/High/Medium/Low) để các bên dễ so sánh và ưu tiên xử lý lỗ hổng.", "hint": "Viết tắt hệ thống chấm điểm mức độ nghiêm trọng lỗ hổng, hay dùng phiên bản 3.1."}, {"prompt": "Khi viết mô tả một lỗ hổng cụ thể trong báo cáo, dù account hay dữ liệu dùng để test là giả định (test account), nguyên tắc nào về việc hiển thị thông tin xác thực cần được tuân thủ để tránh rủi ro bảo mật cho chính báo cáo?", "patterns": ["không.*(hiển thị|hiện).*mật khẩu", "mask.*credential", "clear text"], "explanation": "Thông tin xác thực (mật khẩu, token, v.v.) không nên bao giờ xuất hiện dạng rõ (clear text) trong báo cáo, dù đó chỉ là tài khoản test, để tránh báo cáo chính nó trở thành nguồn rò rỉ thông tin nếu bị lộ.", "hint": "Liên quan đến việc không bao giờ ghi mật khẩu/thông tin xác thực dạng rõ trong báo cáo, dù chỉ là tài khoản test."}, {"prompt": "Phần phụ lục của báo cáo cần ghi lại những thay đổi được thực hiện trong quá trình kiểm tra (ví dụ file đã upload lên hệ thống mục tiêu). Mục đích chính của việc ghi lại các ''assessment artefacts'' này là gì?", "patterns": ["phân biệt.*(pentest|tấn công thật)", "blue team", "incident response", "giúp.*đội.*phân biệt"], "explanation": "Ghi lại các artefact (dấu vết thay đổi) do pentester để lại giúp đội phòng thủ (blue team) sau này phân biệt được đâu là hoạt động từ đợt kiểm tra hợp pháp, đâu là tấn công thật nếu phát hiện dấu vết tương tự.", "hint": "Giúp đội vận hành/bảo mật sau này phân biệt dấu vết pentest hợp pháp với một cuộc tấn công thật."}], "difficulty": "co_ban", "cert_tags": ["THM PT1", "THM WEB1"], "challenge_key": "THM:Writing Pentest Reports"}')

